}
async function extrairAtributosDaCarta(carta) {
    const atributos = {};
    const paresBrutos = [];
    if (!carta)
        return { atributos, paresBrutos };
    const dados = await obterDadosCustomizadosDaCarta(carta);
    for (let i = 1; i <= 3; i++) {
        const rotulo = String(dados[`atributo${i}`] ?? dados[`atributo_${i}`] ?? "").trim();
        if (!rotulo || ["null", "undefined", "nenhum", "-"].includes(rotulo.toLowerCase()))
            continue;
        const valorNumerico = Number(String(dados[`valor${i}`] ?? dados[`valor_${i}`] ?? "0").trim().replace(",", "."));
        if (Number.isNaN(valorNumerico) || !Number.isFinite(valorNumerico))
            continue;
        paresBrutos.push(`${rotulo}=${valorNumerico}`);
        const chaveAtributo = rotulo
            .toLowerCase()
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .replace(/\s+/g, " ");
        if (!atributos[chaveAtributo])
            atributos[chaveAtributo] = { rotulo, valor: 0 };
        atributos[chaveAtributo].valor += valorNumerico;
    }
    return { atributos, paresBrutos };
}
async function calcularPontuacao(cartaOcorrencia, cartasAtaque) {
    const leituraOcorrencia = await extrairAtributosDaCarta(cartaOcorrencia);
    const somaAcao = {};
    for (const cartaAcao of cartasAtaque) {
        const leituraAcao = await extrairAtributosDaCarta(cartaAcao);
        for (const [chave, info] of Object.entries(leituraAcao.atributos)) {
            if (!somaAcao[chave])
                somaAcao[chave] = { rotulo: info.rotulo, valor: 0 };
            somaAcao[chave].valor += info.valor;
        }
    }
    let totalRequerido = 0, totalAtendido = 0;
    for (const [chave, infoOcorrencia] of Object.entries(leituraOcorrencia.atributos)) {
        const requerido = Math.max(0, infoOcorrencia.valor);
        if (requerido <= 0)
            continue;
        const obtido = Math.max(0, somaAcao[chave]?.valor ?? 0);
        totalRequerido += requerido;
        totalAtendido += Math.min(obtido, requerido);
    }
    if (totalRequerido === 0)
        return { pontos: 0, percentual: 0, passosDebug: [] };
    const proporcao = Math.min(1, totalAtendido / totalRequerido);
    return {
        pontos: Number((proporcao * 10).toFixed(2)),
        percentual: Number((proporcao * 100).toFixed(2)),
        passosDebug: [],
    };
}
