            break;
        if (estado.ocupado)
            continue;
        estado.ocupado = true;
        try {
            if (estado.faseAtual === "FASE_3") {
                await verificarNovosAssentosOcupados();
                await prepararCartasNosSnapPointsDeAtaque();
                const deckAcao = await obterObjetoPorNome("Deck_Acao");
                if (deckAcao && Boolean(deckAcao.faceUp) !== estado.deckAcaoFaceUpBase) {
                    if (typeof deckAcao.flip === "function") {
                        await deckAcao.flip();
                        await pausaFisica(0.25);
                    }
                    estado.deckAcaoFaceUpBase = Boolean(deckAcao.faceUp);
                    await validarEAvancarParaFase4();
                }
            }
            atualizarHistoricoPosicoes(await listarTodosObjetos());
        }
        finally {
            estado.ocupado = false;
        }
    }
